template<class T> [[gnu::noinline]] std::uint64_t kernel(const std::vector<T>& values) {std::uint64_t result=0;for(auto n:values)result+=is_prime(n);return result;}
static std::uint64_t cpu_ns(){timespec stamp{};clock_gettime(CLOCK_PROCESS_CPUTIME_ID,&stamp);return std::uint64_t(stamp.tv_sec)*1000000000+std::uint64_t(stamp.tv_nsec);}
template<class T> static void run(int mode,std::size_t count){
 std::mt19937_64 random(202610221545);std::vector<T> values;values.reserve(count);
 constexpr unsigned primes[]{2,3,5,7,11,13,17};
 for(std::size_t i=0;i<count;++i){
  std::uint64_t value=random();
  if(mode==1)value&=~std::uint64_t{1};
  if(mode>=2&&mode<=7){const auto p=primes[mode-1];auto k=(value&((std::uint64_t{1}<<59)-1))|(std::uint64_t{1}<<40)|1;while(std::gcd(k,std::uint64_t{510510})!=1)k+=2;value=k*p;}
  if(mode==9)value=i%1024;
  values.push_back(static_cast<T>(value));
 }
 const auto t0=cpu_ns();std::atomic_signal_fence(std::memory_order_seq_cst);const auto checksum=kernel(values);std::atomic_signal_fence(std::memory_order_seq_cst);const auto t1=cpu_ns();
 if(mode>=1&&mode<=7&&checksum!=0)std::abort();
 std::printf("%ju %ju\n",static_cast<std::uintmax_t>(t1-t0),static_cast<std::uintmax_t>(checksum));
}
