        return MillerRabin(value, {2, 7, 61});
    if (value < (std::uint64_t{1} << 62))
        return reinsirk::detail::MillerRabin64<true>(value).test_deterministic();
    return reinsirk::detail::MillerRabin64<false>(value).test_deterministic();
